def add_aliases(apps, schema_editor):
    HomeChannel = apps.get_model("home", "HomeChannel")
    for (country, city), extra in EXTRA_ALIASES.items():
        channel = HomeChannel.objects.filter(country=country, city=city).first()
        if channel is None:
            continue
        current = [part.strip() for part in (channel.aliases or "").replace("\n", ",").split(",") if part.strip()]
        known = {part.casefold() for part in current}
        added = [name for name in extra if name.casefold() not in known]
        if added:
            channel.aliases = ", ".join(current + added)
            channel.save(update_fields=["aliases"])


